static JSValue js_Window_get_mouse_passthrough_polygon(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "Window.mouse_passthrough_polygon getter: missing handle");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "Window.mouse_passthrough_polygon getter: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "Window.mouse_passthrough_polygon getter: invalid object");
    }

    Window* typed_obj = Object::cast_to<Window>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "Window.mouse_passthrough_polygon getter: wrong type");
    }

    PackedVector2Array value = typed_obj->get_mouse_passthrough_polygon();
    JSValue arr = JS_NewArray(ctx);
    for (int i = 0; i < value.size(); i++) {
        JSValue vec = JS_NewObject(ctx);
        JS_SetPropertyStr(ctx, vec, "x", JS_NewFloat64(ctx, value[i].x));
        JS_SetPropertyStr(ctx, vec, "y", JS_NewFloat64(ctx, value[i].y));
        JS_SetPropertyUint32(ctx, arr, i, vec);
    }
    return arr;
}

// Property setter: Window::mouse_passthrough_polygon
static JSValue js_Window_set_mouse_passthrough_polygon(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 2) {
        return JS_ThrowTypeError(ctx, "Window.mouse_passthrough_polygon setter: missing arguments");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "Window.mouse_passthrough_polygon setter: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "Window.mouse_passthrough_polygon setter: invalid object");
    }

    Window* typed_obj = Object::cast_to<Window>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "Window.mouse_passthrough_polygon setter: wrong type");
    }

    PackedVector2Array value;
    if (JS_IsArray(argv[1])) {
        JSValue len_val = JS_GetPropertyStr(ctx, argv[1], "length");
        int64_t len = 0; JS_ToInt64(ctx, &len, len_val); JS_FreeValue(ctx, len_val);
        value.resize(len);
        for (int64_t i = 0; i < len; i++) {
            JSValue elem = JS_GetPropertyUint32(ctx, argv[1], i);
            double x = 0, y = 0;
            JSValue jx = JS_GetPropertyStr(ctx, elem, "x");
            JSValue jy = JS_GetPropertyStr(ctx, elem, "y");
            JS_ToFloat64(ctx, &x, jx); JS_ToFloat64(ctx, &y, jy);
            JS_FreeValue(ctx, jx); JS_FreeValue(ctx, jy);
            JS_FreeValue(ctx, elem);
            value.set(i, Vector2(x, y));
        }
    }
    typed_obj->set_mouse_passthrough_polygon(value);
    return JS_UNDEFINED;
}

